use verus::prelude::*;

verus! {
    /// Given a line of length `n` (positions 1..=n), two distinct
    /// starting positions `a` and `b`, and up to `x` unit‐moves
    /// (each move shifts one of the positions by ±1 but stays in [1,n]),
    /// compute the maximum possible distance between them after at most
    /// `x` moves.  In fact the answer is
    ///    min(|a−b| + x, n−1).
    pub proof fn solve_rival_distance(n: i8, x: i8, a: i8, b: i8) -> (result: i8)
        requires
            // problem constraints
            2 <= n && n <= 100,
            0 <= x && x <= 100,
            1 <= a && a <= n,
            1 <= b && b <= n,
            a != b,
        ensures
            // result is exactly min(|a−b| + x, n−1), expressed at spec‐level
            result as int ==
                std::cmp::min(
                    (if a >= b { a - b } else { b - a }) as int + x as int,
                    (n - 1) as int
                ),
        ensures
            // result falls in the valid range [0, n−1]
            0 <= result && result <= n - 1,
    {
        // compute the absolute difference |a - b|
        let d: i8 =
            if a >= b {
                a - b
            } else {
                b - a
            };
        // do the addition in a larger integer to avoid i8 overflow
        let sum_i16: i16 = (d as i16) + (x as i16);
        let max_sep_i16: i16 = (n - 1) as i16;
        // take the minimum
        let best_i16: i16 =
            if sum_i16 <= max_sep_i16 {
                sum_i16
            } else {
                max_sep_i16
            };
        // cast back to i8 for the result
        let res: i8 = best_i16 as i8;
        // sanity‐check the bounds
        assert(res >= 0);
        assert(res <= n - 1);
        result = res;
    }
}